// Создание ордера
public static str createOrder(RMarketTable _market, RMarketApiKey _apiKey)
{
    RMarketMethodInterface_CreateOrder apiMethod = RMarketMethodInterface::CreateOrder(_market.ApiType);
    apiMethod.setBaseUrl(_market.ApiUrl);
    apiMethod.setApiKey(_apiKey);
    apiMethod.initParameters("BTCUSDT", "BUY", "MARKET", "0.0001", "50000");
    apiMethod.execute();
    str createdOrderId = apiMethod.getOrderId();
    return createdOrderId;
}

// Отмена ордера
public static str cancelOrder(RMarketTable _market, RMarketApiKey _apiKey, str _orderId)
{
    RMarketMethodInterface_CancelOrder apiMethod = RMarketMethodInterface::CancelOrder(_market.ApiType);
    apiMethod.setBaseUrl(_market.ApiUrl);
    apiMethod.setApiKey(_apiKey);
    apiMethod.initParameters("BTCUSDT", _orderId);
    apiMethod.execute();
    str canceledOrderId = apiMethod.getOrderId();
    return canceledOrderId;
}
